// Night market oasis: starry indigo sky, crescent moon, paper lanterns strung between palms and warm reflections in the pool.
export const meta = {
  title: "Lantern Night Oasis",
  kind: "illustration",
  description: "A flat-style desert night market scene with a crescent moon, glowing paper lanterns strung between palms and warm light dancing on the pool, for festive editorials, event posters and evening campaign heroes.",
  tags: ["night market", "lanterns", "oasis", "desert", "crescent moon", "starry night", "festival", "flat illustration"],
  price: 9,
  author: "Pat Liu",
  size: [1200, 800],
};

export const params = {
  knobs: {
    sky: { type: "color", label: "Night sky", default: "#141E4A" },
    moon: { type: "color", label: "Moon & stars", default: "#F6E9C4" },
    sand: { type: "color", label: "Sand", default: "#4C4F7E" },
    water: { type: "color", label: "Water", default: "#203A72" },
    palm: { type: "color", label: "Palms", default: "#0E1430" },
    lantern: { type: "color", label: "Lantern glow", default: "#FFB347" },
    style: { type: "choice", label: "Lantern shape", default: "mixed", options: ["round", "tall", "mixed"] },
    lanterns: { type: "range", label: "Lanterns per string", default: 5, min: 2, max: 9, step: 1 },
    palms: { type: "range", label: "Palm trees", default: 3, min: 2, max: 4, step: 1 },
    seed: { type: "range", label: "Seed", default: 42, min: 1, max: 300, step: 1 },
  },
  presets: {
    "Indigo Bazaar": { sky: "#141E4A", moon: "#F6E9C4", sand: "#4C4F7E", water: "#203A72", palm: "#0E1430", lantern: "#FFB347" },
    "Saffron Night": { sky: "#2A1838", moon: "#FFE9C2", sand: "#6A4560", water: "#2C2F5E", palm: "#170C1F", lantern: "#FF8A3D" },
    "Jade Lanterns": { sky: "#0C2A33", moon: "#E8F3DA", sand: "#355B5E", water: "#174A57", palm: "#061A1E", lantern: "#FFD56B" },
    "Rose Midnight": { sky: "#231A45", moon: "#FCE6EC", sand: "#5B4A7E", water: "#2E3A78", palm: "#120E2A", lantern: "#FF7A8A" },
  },
};

function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const hex = (c) => { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
const mix = (a, b, t) => { const A = hex(a), B = hex(b); return "#" + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, "0")).join(""); };
const f = (n) => n.toFixed(1);
const pt = (q) => `${f(q[0])},${f(q[1])}`;

function dune(r, W, H, base, amp, humps) {
  const n = humps * 2, ws = [];
  for (let i = 0; i < n; i++) ws.push(0.7 + 0.6 * r());
  const sum = ws.reduce((a, b) => a + b, 0);
  const pts = [];
  let x = -80;
  for (let i = 0; i <= n; i++) {
    const peak = i % 2 === 1;
    pts.push([x, peak ? base - amp * (0.55 + 0.45 * r()) : base + r() * amp * 0.12, peak]);
    if (i < n) x += (ws[i] / sum) * (W + 160);
  }
  let d = `M${pt(pts[0])}`;
  for (let i = 1; i < pts.length; i++) {
    const [x0, y0] = pts[i - 1], [x1, y1] = pts[i], h = (x1 - x0) / 2;
    d += ` C${f(x0 + h)},${f(y0)} ${f(x1 - h)},${f(y1)} ${pt([x1, y1])}`;
  }
  return { d: d + ` L${W + 80},${H} L-80,${H}Z`, pts };
}

function shadows(pts, side) {
  let s = "";
  for (let i = 1; i < pts.length - 1; i++) {
    if (!pts[i][2]) continue;
    const A = pts[i], B = pts[i + side], dx = B[0] - A[0];
    s += `M${pt(A)} C${f(A[0] + dx / 2)},${f(A[1])} ${f(B[0] - dx / 2)},${f(B[1])} ${pt(B)} C${f(B[0] - dx * 0.55)},${f(B[1])} ${f(A[0] + dx * 0.08)},${f(A[1] + (B[1] - A[1]) * 0.55)} ${pt(A)}Z`;
  }
  return s;
}

function frondPath(x, y, ang, L) {
  const a = (ang * Math.PI) / 180, dx = Math.cos(a), dy = Math.sin(a);
  const P0 = [x, y], C = [x + dx * L * 0.55, y + dy * L * 0.55 - L * 0.2];
  const P2 = [x + dx * L, y + dy * L + L * (0.16 + 0.26 * Math.abs(dx))];
  const B = (t) => { const u = 1 - t; return [u * u * P0[0] + 2 * u * t * C[0] + t * t * P2[0], u * u * P0[1] + 2 * u * t * C[1] + t * t * P2[1]]; };
  const T = (t) => {
    const tx = 2 * (1 - t) * (C[0] - P0[0]) + 2 * t * (P2[0] - C[0]), ty = 2 * (1 - t) * (C[1] - P0[1]) + 2 * t * (P2[1] - C[1]);
    const l = Math.hypot(tx, ty) || 1; return [tx / l, ty / l];
  };
  const N = 14, Wd = L * 0.14, up = [], dn = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N, odd = i % 2 === 1, tt = odd ? Math.min(1, t + 0.05) : t;
    const P = B(tt), Tq = T(tt);
    const w = Wd * Math.pow(Math.max(0, Math.sin(Math.PI * Math.pow(t, 0.75))), 0.8) * (odd ? 1 : 0.4);
    up.push([P[0] - Tq[1] * w, P[1] + Tq[0] * w]);
    dn.push([P[0] + Tq[1] * w, P[1] - Tq[0] * w]);
  }
  return "M" + up.map(pt).join("L") + "L" + dn.reverse().map(pt).join("L") + "Z";
}

const trunkAt = (h, lean, t) => { const u = 1 - t; return [2 * u * t * lean * 0.8 + t * t * lean, 2 * u * t * -h * 0.5 + t * t * -h]; };

function palm(r, h, lean, c) {
  const C = [lean * 0.8, -h * 0.5], E = [lean, -h];
  const at = (t) => trunkAt(h, lean, t);
  const tan = (t) => {
    const x = 2 * (1 - t) * C[0] + 2 * t * (E[0] - C[0]), y = 2 * (1 - t) * C[1] + 2 * t * (E[1] - C[1]);
    const l = Math.hypot(x, y); return [x / l, y / l];
  };
  const wAt = (t) => h * (0.034 - 0.014 * t + 0.022 * Math.pow(1 - t, 6));
  const Ls = [], Rs = [];
  for (let i = 0; i <= 12; i++) {
    const t = i / 12, P = at(t), T = tan(t), w = wAt(t);
    Ls.push([P[0] - T[1] * w, P[1] + T[0] * w]);
    Rs.push([P[0] + T[1] * w, P[1] - T[0] * w]);
  }
  let s = `<path d="M${Ls.map(pt).join("L")}L${Rs.reverse().map(pt).join("L")}Z" fill="${c.trunk}"/>`;
  if (c.ring) {
    let d = "";
    for (let t = 0.12; t < 0.92; t += 0.075) {
      const P = at(t), T = tan(t), w = wAt(t) * 0.85;
      d += `M${pt([P[0] - T[1] * w, P[1] + T[0] * w])}L${pt([P[0] - T[0] * w * 0.5, P[1] - T[1] * w * 0.5])}L${pt([P[0] + T[1] * w, P[1] - T[0] * w])}`;
    }
    s += `<path d="${d}" fill="none" stroke="${c.ring}" stroke-width="${f(Math.max(1.4, h * 0.008))}" stroke-linecap="round" stroke-linejoin="round"/>`;
  }
  const len = () => h * 0.38 * (0.9 + 0.2 * r());
  const jit = () => (r() - 0.5) * 14;
  [-138, -98, -58].forEach((a) => { s += `<path d="${frondPath(E[0], E[1], a + jit(), len() * 0.9)}" fill="${c.back}"/>`; });
  [-182, -152, -120, -84, -48, -12, 148, 32].forEach((a) => { s += `<path d="${frondPath(E[0], E[1], a + jit(), len())}" fill="${c.frond}"/>`; });
  s += `<circle cx="${f(E[0])}" cy="${f(E[1])}" r="${f(h * 0.028)}" fill="${c.frond}"/>`;
  return s;
}

function tuft(r, x, y, sz, col) {
  const n = 4 + Math.floor(r() * 3);
  let d = "";
  for (let i = 0; i < n; i++) {
    const k = i / (n - 1) - 0.5, a = -Math.PI / 2 + k * 1.5 + (r() - 0.5) * 0.2, L = sz * (0.7 + 0.4 * r()) * (1 - Math.abs(k) * 0.6);
    d += `M${f(x)},${f(y)} Q${f(x + Math.cos(a) * L * 0.3)},${f(y + Math.sin(a) * L * 0.75)} ${f(x + Math.cos(a) * L)},${f(y + Math.sin(a) * L)}`;
  }
  return `<path d="${d}" fill="none" stroke="${col}" stroke-width="2.6" stroke-linecap="round"/>`;
}

function lamp(x, y, s, tall, gid, cap) {
  const top = y + 7;
  let g = `<path d="M${f(x)},${f(y)}V${f(top)}" stroke="${cap}" stroke-width="1.4"/>`;
  if (tall) {
    const w = s * 1.3, h = s * 2.1, by = top + s * 0.2;
    g += `<rect x="${f(x - w / 2)}" y="${f(by)}" width="${f(w)}" height="${f(h)}" rx="${f(s * 0.4)}" fill="url(#${gid})"/>`;
    g += `<path d="M${f(x - w / 2)},${f(by + h * 0.33)}h${f(w)}M${f(x - w / 2)},${f(by + h * 0.66)}h${f(w)}" stroke="${cap}" stroke-width="1.1" opacity="0.35"/>`;
    g += `<rect x="${f(x - w * 0.36)}" y="${f(top)}" width="${f(w * 0.72)}" height="${f(s * 0.32)}" rx="1.5" fill="${cap}"/><rect x="${f(x - w * 0.36)}" y="${f(by + h - s * 0.12)}" width="${f(w * 0.72)}" height="${f(s * 0.32)}" rx="1.5" fill="${cap}"/>`;
    return { g: g + `<path d="M${f(x)},${f(by + h + s * 0.2)}v${f(s * 0.7)}" stroke="${cap}" stroke-width="1.6" stroke-linecap="round"/>`, cy: by + h / 2 };
  }
  const by = top + s * 0.22 + s * 0.85;
  g += `<ellipse cx="${f(x)}" cy="${f(by)}" rx="${f(s)}" ry="${f(s * 0.85)}" fill="url(#${gid})"/>`;
  g += `<ellipse cx="${f(x)}" cy="${f(by)}" rx="${f(s * 0.45)}" ry="${f(s * 0.85)}" fill="none" stroke="${cap}" stroke-width="1.1" opacity="0.35"/>`;
  g += `<rect x="${f(x - s * 0.42)}" y="${f(top)}" width="${f(s * 0.84)}" height="${f(s * 0.26)}" rx="1.5" fill="${cap}"/><rect x="${f(x - s * 0.42)}" y="${f(by + s * 0.72)}" width="${f(s * 0.84)}" height="${f(s * 0.26)}" rx="1.5" fill="${cap}"/>`;
  return { g: g + `<path d="M${f(x)},${f(by + s * 0.98)}v${f(s * 0.7)}" stroke="${cap}" stroke-width="1.6" stroke-linecap="round"/>`, cy: by };
}

export default function render(p) {
  const W = 1200, H = 800, HZ = 480;
  const r = rng(p.seed * 9973 + 17), tr = rng(p.seed * 7 + 3), lr = rng(p.seed * 31 + 11);
  const shade = mix(p.sky, "#000000", 0.45);
  const moonRight = r() > 0.35;
  const sx = W * (moonRight ? 0.7 + r() * 0.14 : 0.14 + r() * 0.14), sy = 168, sr = 54;
  const cx = W * (0.42 + r() * 0.16), cy = 660, rx = 258, ry = 52;
  const haze = mix(p.sand, p.sky, 0.55), deep = mix(p.sand, shade, 0.22);
  const alt = mix(p.lantern, "#E0442E", 0.55);

  let defs = `<linearGradient id="sky" x1="0" y1="0" x2="0" y2="${HZ}" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="${mix(p.sky, "#000000", 0.2)}"/><stop offset="0.6" stop-color="${p.sky}"/><stop offset="1" stop-color="${mix(p.sky, p.lantern, 0.2)}"/></linearGradient>`;
  defs += `<linearGradient id="wa" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${mix(p.water, shade, 0.35)}"/><stop offset="1" stop-color="${mix(p.water, p.sky, 0.25)}"/></linearGradient>`;
  defs += `<radialGradient id="lg"><stop offset="0" stop-color="${p.lantern}" stop-opacity="0.55"/><stop offset="0.35" stop-color="${p.lantern}" stop-opacity="0.18"/><stop offset="1" stop-color="${p.lantern}" stop-opacity="0"/></radialGradient>`;
  defs += `<radialGradient id="gg"><stop offset="0" stop-color="${p.lantern}" stop-opacity="0.22"/><stop offset="1" stop-color="${p.lantern}" stop-opacity="0"/></radialGradient>`;
  [["lb", p.lantern], ["lb2", alt]].forEach(([id, c]) => { defs += `<radialGradient id="${id}" cx="0.42" cy="0.4" r="0.7"><stop offset="0" stop-color="${mix(c, "#FFFFFF", 0.65)}"/><stop offset="0.55" stop-color="${c}"/><stop offset="1" stop-color="${mix(c, shade, 0.3)}"/></radialGradient>`; });
  defs += `<filter id="bl" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="4"/></filter>`;
  defs += `<clipPath id="pool"><ellipse cx="${f(cx)}" cy="${cy}" rx="${rx}" ry="${ry}"/></clipPath>`;
  defs += `<mask id="orb" maskUnits="userSpaceOnUse" x="0" y="0" width="${W}" height="${H}"><rect width="${W}" height="${H}" fill="#fff"/><circle cx="${f(sx + sr * 0.42)}" cy="${f(sy - sr * 0.28)}" r="${f(sr * 0.88)}" fill="#000"/></mask>`;

  let sky = `<rect width="${W}" height="${H}" fill="url(#sky)"/>`;
  const st = rng(p.seed * 13 + 5);
  let spark = "";
  for (let i = 0; i < 150; i++) {
    const x = st() * W, y = st() * (HZ - 90), rr = 0.6 + st() * 1.3, o = (0.3 + st() * 0.6) * (1 - (y / HZ) * 0.5);
    if (Math.hypot(x - sx, y - sy) < sr * 1.7) continue;
    if (i % 23 === 0) { const k = 5 + rr * 3; spark += `M${f(x)},${f(y - k)}Q${f(x)},${f(y)} ${f(x + k)},${f(y)}Q${f(x)},${f(y)} ${f(x)},${f(y + k)}Q${f(x)},${f(y)} ${f(x - k)},${f(y)}Q${f(x)},${f(y)} ${f(x)},${f(y - k)}Z`; }
    else sky += `<circle cx="${f(x)}" cy="${f(y)}" r="${f(rr)}" fill="${p.moon}" opacity="${o.toFixed(2)}"/>`;
  }
  sky += `<path d="${spark}" fill="${p.moon}" opacity="0.9"/>`;
  sky += `<circle cx="${f(sx)}" cy="${sy}" r="${f(sr * 2.2)}" fill="${p.moon}" opacity="0.05"/><circle cx="${f(sx)}" cy="${sy}" r="${f(sr * 1.5)}" fill="${p.moon}" opacity="0.07"/><circle cx="${f(sx)}" cy="${sy}" r="${sr}" fill="${p.moon}" mask="url(#orb)"/>`;

  let land = "";
  const n = 4, side = moonRight ? -1 : 1;
  for (let i = 0; i < n; i++) {
    const t = i / (n - 1), u = i / n, col = mix(haze, deep, t);
    const dn = dune(r, W, H, 478 + u * 100, 95 - 45 * u, 2 + Math.floor(r() * 2));
    land += `<path d="${dn.d}" fill="${col}"/><path d="${shadows(dn.pts, side)}" fill="${mix(col, shade, 0.25 + 0.25 * t)}"/>`;
  }
  land += `<path d="${dune(r, W, H, 592, 14, 3).d}" fill="${p.sand}"/>`;
  land += `<ellipse cx="${f(cx)}" cy="${cy - 60}" rx="560" ry="230" fill="url(#gg)"/>`;

  const slots = [[215, 330, 44], [338, 262, -52], [164, 206, -34], [24, 188, 58]];
  const pl = slots.slice(0, p.palms).map(([deg, h, lean], i) => {
    const th = ((deg + (r() - 0.5) * 10) * Math.PI) / 180;
    return { x: cx + (rx + 20) * Math.cos(th), y: cy + (ry + 10) * Math.sin(th), h: h * (0.9 + 0.2 * r()), lean: lean + (r() - 0.5) * 24, s: p.seed * 131 + i * 17 };
  }).sort((a, b) => a.y - b.y);
  const trunk = mix(shade, p.palm, 0.35);
  const cols = { trunk, ring: mix(trunk, p.lantern, 0.22), frond: p.palm, back: mix(p.palm, p.sky, 0.25) };
  const rc = mix(p.water, p.palm, 0.5);
  const mono = { trunk: rc, ring: null, frond: rc, back: rc };

  pl.forEach((o) => { land += `<ellipse cx="${f(o.x + side * o.h * 0.13)}" cy="${f(o.y + 3)}" rx="${f(o.h * 0.17)}" ry="6" fill="${shade}" opacity="0.3"/>`; });
  land += `<ellipse cx="${f(cx)}" cy="${cy}" rx="${rx + 16}" ry="${ry + 9}" fill="${mix(p.sand, shade, 0.28)}"/>`;
  land += `<ellipse cx="${f(cx)}" cy="${cy}" rx="${rx + 6}" ry="${ry + 4}" fill="${mix(p.sand, shade, 0.42)}"/>`;
  land += `<ellipse cx="${f(cx)}" cy="${cy}" rx="${rx}" ry="${ry}" fill="url(#wa)"/>`;

  const cap = mix(p.palm, p.lantern, 0.15);
  const byX = [...pl].sort((a, b) => a.x - b.x);
  const anchors = byX.map((o) => { const q = trunkAt(o.h, o.lean, 0.8); return [o.x + q[0], o.y + q[1]]; });
  let strings = "", glows = "", bodies = "", refl = "";
  for (let i = 0; i < anchors.length - 1; i++) {
    const A = anchors[i], B = anchors[i + 1], sag = 24 + Math.abs(B[0] - A[0]) * 0.1;
    const C = [(A[0] + B[0]) / 2, (A[1] + B[1]) / 2 + 2 * sag];
    strings += `M${pt(A)}Q${pt(C)} ${pt(B)}`;
    for (let k = 0; k < p.lanterns; k++) {
      const t = (k + 1) / (p.lanterns + 1), u = 1 - t;
      const x = u * u * A[0] + 2 * u * t * C[0] + t * t * B[0], y = u * u * A[1] + 2 * u * t * C[1] + t * t * B[1];
      const s = 10 + lr() * 4;
      const tall = p.style === "tall" || (p.style === "mixed" && (k + i) % 2 === 1);
      const L = lamp(x, y, s, tall, (k + i) % 3 === 1 ? "lb2" : "lb", cap);
      glows += `<circle cx="${f(x)}" cy="${f(L.cy)}" r="${f(s * 4.2)}" fill="url(#lg)"/>`;
      bodies += L.g;
      const yr = cy - ry * 0.55 + Math.min(1, Math.max(0, (cy - ry - L.cy) / 380)) * ry * 1.15;
      refl += `<ellipse cx="${f(x)}" cy="${f(yr)}" rx="${f(s * 1.7)}" ry="${f(s * 0.7)}" fill="${p.lantern}" opacity="0.45" filter="url(#bl)"/>`;
      let d = "";
      for (let j = 0; j < 3; j++) { const w = s * (1.6 - j * 0.45); d += `M${f(x - w / 2)},${f(yr - 3 + j * 7)}h${f(w)}`; }
      refl += `<path d="${d}" stroke="${mix(p.lantern, "#FFFFFF", 0.25)}" stroke-width="2.6" stroke-linecap="round" opacity="0.75"/>`;
    }
  }

  let pool = pl.map((o) => `<g transform="translate(${f(o.x)},${f(Math.max(o.y, cy - ry))}) scale(1,-0.58)" opacity="0.85">${palm(rng(o.s), o.h, o.lean, mono)}</g>`).join("");
  const sxr = Math.max(cx - rx * 0.6, Math.min(cx + rx * 0.6, sx));
  let glint = "", rip = "";
  for (let k = 0; k < 4; k++) { const w = sr * (0.9 - k * 0.18); glint += `M${f(sxr - w / 2)},${f(cy - ry * 0.5 + k * ry * 0.27)}h${f(w)}`; }
  for (let k = 0; k < 8; k++) {
    const yy = cy - ry * 0.7 + k * ry * 0.2, half = rx * Math.sqrt(Math.max(0, 1 - ((yy - cy) / ry) ** 2));
    const len = half * (0.25 + 0.4 * tr()), x0 = cx - half + tr() * (2 * half - len);
    rip += `M${f(x0)},${f(yy)}h${f(len)}`;
  }
  pool += `<path d="${rip}" stroke="${mix(p.water, p.sky, 0.6)}" stroke-width="2.2" stroke-linecap="round" opacity="0.7"/>`;
  pool += `<path d="${glint}" stroke="${p.moon}" stroke-width="4" stroke-linecap="round" opacity="0.55"/>`;
  pool += refl;
  land += `<g clip-path="url(#pool)">${pool}</g>`;

  const tc = mix(p.palm, p.sand, 0.15);
  let back = "", front = "";
  for (let i = 0; i < 7; i++) {
    const th = tr() * Math.PI * 2, sz = 16 + tr() * 12;
    const t = tuft(tr, cx + (rx + 14) * Math.cos(th), cy + (ry + 8) * Math.sin(th), sz, tc);
    if (Math.sin(th) < 0) back += t; else front += t;
  }
  const palms = pl.map((o) => `<g transform="translate(${f(o.x)},${f(o.y)})">${palm(rng(o.s), o.h, o.lean, cols)}</g>`).join("");
  const lights = `<path d="${strings}" fill="none" stroke="${mix(p.palm, p.lantern, 0.3)}" stroke-width="1.6"/>${glows}${bodies}`;

  const flip = tr() < 0.5 ? "" : ` transform="translate(${W},0) scale(-1,1)"`;
  const lip = `<g${flip}><path d="M0,${H} L0,712 C140,690 300,708 470,${H}Z" fill="${mix(p.sand, shade, 0.25)}"/><path d="M0,${H} L0,748 C130,735 250,752 360,${H}Z" fill="${mix(p.sand, shade, 0.42)}"/>${tuft(tr, 120, 704, 26, tc)}${tuft(tr, 236, 712, 20, tc)}</g>`;

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}"><defs>${defs}</defs>${sky}${land}${back}${palms}${lights}${front}${lip}</svg>`;
}
